style.css:
@-moz-document domain("google.com") {
/* 1. ФИРМЕННЫЙ ШРИФТ XIAOMI (MI SANS) */
    /* Используем Roboto, который очень похож на Mi Sans и доступен */
    body, textarea, input, select {
        font-family: 'Roboto', 'Noto Sans', sans-serif !important;
    }

    /* 2. ГРАФИКА XIAOMI (Скругление и тени) */
    .RNNXgb {
        border-radius: 18px !important; /* Умеренное скругление, как в MIUI */
        box-shadow: 0 4px 10px rgba(255, 103, 0, 0.2), 0 0 5px rgba(255, 103, 0, 0.1) !important; 
        border: none !important;
    }

    /* 3. ОРАНЖЕВЫЙ ЦВЕТ XIAOMI (АКЦЕНТ) */
    .gNO89b, .Tg7LZd, .z1asce {
        background-color: #ff6700 !important; /* Насыщенный оранжевый Xiaomi */
        border: none !important;
        color: white !important;
        border-radius: 8px !important;
    }

    /* 4. ЗАМЕНА ЛОГОТИПА на оранжевый текст (Имитация) */
    /* Скрываем обычный логотип */
    .lnXdpd {
        visibility: hidden;
    }
    
    /* Добавляем стилизованный оранжевый текст "XIAOMI" */
    .lnXdpd:after {
        content: "XIAOMI"; /* Вставляем слово XIAOMI */
        visibility: visible;
        font-size: 80px; /* Размер, как у лого */
        font-weight: bold;
        color: #ff6700; /* Оранжевый цвет */
        position: absolute;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%); /* Центрирование */
    }
}
